row(16, 12, 'MATERIAL', f'AND YOU SHALL REMEMBER THAT YOU WERE A SLAVE IN EGYPT, AND YOU SHALL KEEP AND DO THESE STATUTES. {HP(16, 12, (("וזכרת", "כי", "עבד", "היית", "במצרים"), "and you shall remember that you were a slave in Egypt — the book\'s five seats, 24:18 the closest"), (("ושמרת", "ועשית", "את", "החקים", "האלה"), "and you shall keep and do THESE statutes — the limiting word"))} {AP(16, 12, (("ותדכר", "ארי", "עבדא", "הויתא", "במצרים"), "and you shall remember that you were a slave in Egypt"), (("ית", "קימיא", "האלין"), "these statutes"))} THESE: 139:1\'s assembly and the other feasts\' rites. Fresh.')
row(16, 13, 'MATERIAL', f'THE FEAST OF BOOTHS YOU SHALL KEEP FOR YOURSELF SEVEN DAYS, WHEN YOU GATHER IN FROM YOUR THRESHING-FLOOR AND YOUR WINEPRESS. {HP(16, 13, (("חג", "הסכת", "תעשה", "לך", "שבעת", "ימים"), "the feast of booths you shall keep for yourself seven days — spelled defective, the Bible\'s one seat"), (("באספך", "מגרנך", "ומיקבך"), "when you gather in from your threshing floor and your winepress"))} {AP(16, 13, (("חגא", "דמטליא", "תעבד", "לך"), "the feast of HUTS you shall make for yourself — the book\'s three seats of the word"), (("במכנשך", "מאדרך", "וממעצרתך"), "when you gather in from your floor and your press"))} THE BOOTH: 140:1-2\'s for yourself and for the Most High; 140:3\'s old booth (the Mishnah); 140:4\'s fellow\'s booth; 140:5\'s lengths; 140:6-7\'s vegetables. Fresh.')
row(16, 14, 'MATERIAL', f'AND YOU SHALL REJOICE IN YOUR FEAST — YOU, YOUR SON AND YOUR DAUGHTER, YOUR MANSERVANT AND YOUR MAIDSERVANT, THE LEVITE, THE SOJOURNER, THE FATHERLESS AND THE WIDOW WITHIN YOUR GATES. {HP(16, 14, (("ושמחת", "בחגך"), "and you shall rejoice in your feast"), (("אתה", "ובנך", "ובתך", "ועבדך", "ואמתך", "והלוי"), "you, your son, your daughter, your manservant, your maidservant, the Levite — 16:11\'s nine, identical"), (("והגר", "והיתום", "והאלמנה", "אשר", "בשעריך"), "the sojourner, the fatherless and the widow within your gates"))} {AP(16, 14, (("ותחדי", "בחגך"), "and you shall rejoice in your feast"), (("די", "בקרויך"), "who are in your cities"))} THE JOY AGAIN: 141:1-2\'s every kind, flesh only; 141:3\'s precedence. Fresh.')
row(16, 15, 'MATERIAL', f'SEVEN DAYS YOU SHALL KEEP THE FEAST TO THE LORD YOUR GOD IN THE PLACE WHICH THE LORD WILL CHOOSE, FOR THE LORD YOUR GOD WILL BLESS YOU IN ALL YOUR PRODUCE AND IN ALL THE WORK OF YOUR HANDS, AND YOU SHALL BE ALTOGETHER JOYFUL. {HP(16, 15, (("שבעת", "ימים", "תחג", "ליהוה"), "seven days you shall keep the feast to the LORD — the chapter\'s fourth \'seven days\'"), (("בכל", "תבואתך", "ובכל", "מעשה", "ידיך"), "in all your produce and in all the work of your hands"), (("והיית", "אך", "שמח"), "and you shall be ALTOGETHER joyful — \'only\' the limiting word"))} {AP(16, 15, (("תחוג", "קדם", "יי"), "you shall keep the feast before the LORD"), (("ותהי", "ברם", "חדי"), "and you shall be ONLY rejoicing"))} THE SEVEN: 142:1-2\'s compensation; 142:3\'s all crops; 142:4-6\'s nights and offerings. Fresh.')
row(16, 16, 'MATERIAL', f'THREE TIMES A YEAR ALL YOUR MALES SHALL APPEAR BEFORE THE LORD YOUR GOD IN THE PLACE WHICH HE WILL CHOOSE — AT THE FEAST OF UNLEAVENED BREAD, AT THE FEAST OF WEEKS AND AT THE FEAST OF BOOTHS — AND NONE SHALL APPEAR BEFORE THE LORD EMPTY. {HP(16, 16, (("שלוש", "פעמים", "בשנה"), "three times a year — spelled full; 2 Chronicles 8:13 the one other"), (("יראה", "כל", "זכורך", "את", "פני", "יהוה"), "all your males shall appear before the LORD — Exodus 23:17 and 34:23"), (("בחג", "המצות", "ובחג", "השבעות", "ובחג", "הסכות"), "at the feast of unleavened bread, of weeks and of booths — the three names in order"), (("ולא", "יראה", "את", "פני", "יהוה", "ריקם"), "and none shall appear before the LORD empty — the one seat"))} {AP(16, 16, (("תלת", "זמנין", "בשתא"), "three TIMES in the year — 143:1\'s seasons"), (("יתחזי", "כל", "דכורך"), "all your males shall be seen"), (("ריקנון",), "empty — one seat"))} THE PILGRIMAGE: 143:1-5\'s times, seeing, males, minors (the Mishnah); 143:7\'s order and the delay; 143:8\'s prices; 52:4\'s guard of the land (the outside row). Fresh.')
row(16, 17, 'MATERIAL', f'EACH MAN AS THE GIFT OF HIS HAND, ACCORDING TO THE BLESSING OF THE LORD YOUR GOD WHICH HE HAS GIVEN YOU. {HP(16, 17, (("איש", "כמתנת", "ידו"), "each man as the gift of his hand"), (("כברכת", "יהוה", "אלהיך", "אשר", "נתן", "לך"), "according to the blessing of the LORD your God which He has given you — 12:15\'s six"))} {AP(16, 17, (("גבר", "כמתנת", "ידיה"), "a man as the gift of his hand"), (("כברכתא", "דיי", "אלהך"), "according to the blessing of the LORD your God"))} THE MEASURE: 143:9\'s mouths and means (the Mishnah); Re\'eh ends here. Fresh.')
row(16, 18, 'MATERIAL', f'JUDGES AND OFFICERS YOU SHALL SET FOR YOURSELF IN ALL YOUR GATES WHICH THE LORD YOUR GOD GIVES YOU, TRIBE BY TRIBE, AND THEY SHALL JUDGE THE PEOPLE WITH RIGHTEOUS JUDGMENT. {HP(16, 18, (("שפטים", "ושטרים", "תתן", "לך"), "judges and officers you shall set for yourself — the pair\'s one seat; Shoftim opens"), (("בכל", "שעריך"), "in all your gates — the book\'s four"), (("לשבטיך",), "for your tribes"), (("ושפטו", "את", "העם", "משפט", "צדק"), "and they shall judge the people with righteous judgment"))} {AP(16, 18, (("דינין", "ופרענין", "תמני", "לך"), "JUDGES AND PUNISHERS you shall appoint for yourself — officers rendered punishers"), (("בכל", "קרויך"), "in all your cities"), (("דין", "דקשוט"), "a judgment of TRUTH"))} THE COURTS: 144:1-4\'s three tiers; 144:5\'s capital power; 144:6\'s compulsion; 144:7\'s appointment. Fresh.')
row(16, 19, 'MATERIAL', f'YOU SHALL NOT WREST JUDGMENT, YOU SHALL NOT RESPECT PERSONS, AND YOU SHALL NOT TAKE A BRIBE, FOR THE BRIBE BLINDS THE EYES OF THE WISE AND PERVERTS THE WORDS OF THE RIGHTEOUS. {HP(16, 19, (("לא", "תטה", "משפט"), "you shall not wrest judgment — the Torah\'s three"), (("לא", "תכיר", "פנים"), "you shall not respect persons — singular here, 1:17\'s plural"), (("ולא", "תקח", "שחד"), "and you shall not take a bribe"), (("כי", "השחד", "יעור", "עיני", "חכמים"), "for the bribe blinds the eyes of THE WISE — Exodus 23:8\'s open-eyed"))} {AP(16, 19, (("לא", "תצלי", "דין"), "you shall not incline a judgment"), (("לא", "תשתמודע", "אפין"), "you shall not recognize faces"), (("ומקלקל", "פתגמין", "תריצין"), "and spoils UPRIGHT words — one seat"))} THE THREE: 144:8-9 on the appointer; 144:10\'s bribe even for truth; 144:11\'s money and capital; 281:1\'s two prohibitions for the sojourner (the outside row). Fresh.')
row(16, 20, 'MATERIAL', f'JUSTICE, JUSTICE YOU SHALL PURSUE, THAT YOU MAY LIVE AND INHERIT THE LAND WHICH THE LORD YOUR GOD GIVES YOU. {HP(16, 20, (("צדק", "צדק", "תרדף"), "justice, justice you shall pursue — the doubling\'s one seat"), (("למען", "תחיה", "וירשת", "את", "הארץ"), "that you may live and inherit the land — one seat; 4:1\'s kin"))} {AP(16, 20, (("קשטא", "קשטא", "תהי", "רדיף"), "TRUTH, TRUTH you shall be pursuing — justice rendered truth"), (("בדיל", "דתיחי", "ותירת"), "so that you may live and inherit"))} THE DOUBLING: 144:12-13\'s two directions; 144:14\'s good court; 144:15\'s land. Fresh.')
row(16, 21, 'MATERIAL', f'YOU SHALL NOT PLANT FOR YOURSELF AN ASHERAH OF ANY TREE BESIDE THE ALTAR OF THE LORD YOUR GOD WHICH YOU SHALL MAKE FOR YOURSELF. {HP(16, 21, (("לא", "תטע", "לך", "אשרה", "כל", "עץ"), "you shall not plant for yourself an asherah of any tree — the asherah bare here and at Exodus 34:13"), (("אצל", "מזבח", "יהוה", "אלהיך"), "beside the altar of the LORD your God"))} {AP(16, 21, (("לא", "תצוב", "לך", "אשרת", "כל", "אילן"), "you shall not plant for yourself an asherah, any TREE — the Aramaic\'s word for a tree"), (("בסטר", "מדבחא"), "at the side of the altar"))} THE ASHERAH: 145:1\'s two prohibitions; 145:2\'s portico and high place; 145:3\'s a fortiori from burning (REREAD); 145:4\'s house. Fresh.')
row(16, 22, 'MATERIAL', f'AND YOU SHALL NOT SET UP FOR YOURSELF A PILLAR, WHICH THE LORD YOUR GOD HATES. {HP(16, 22, (("ולא", "תקים", "לך", "מצבה"), "and you shall not set up for yourself a pillar — the Torah\'s eleven seats of the word"), (("אשר", "שנא", "יהוה", "אלהיך"), "which the LORD your God hates — one seat; 12:31\'s kin"))} {AP(16, 22, (("ולא", "תקים", "לך", "קמא"), "and you shall not set up for yourself a pillar"), (("די", "סני", "יי", "אלהך"), "which the LORD your God hates"))} THE PILLAR: 146:1\'s fathers and sons — the a fortiori to the idol; the verse without a kin in the Bible (asserted). Fresh.')
